node -e "
const [lat1, lon1] = [37.7749, -122.4194];  // San Francisco, CA
const [lat2, lon2] = [42.3396, -71.0693];    // Boston, MA 02118

const R = 6371; // Earth's radius in km
const toRad = d => d * Math.PI / 180;

const dlat = toRad(lat2 - lat1);
const dlon = toRad(lon2 - lon1);
const a = Math.sin(dlat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dlon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
const km = R * c;
const mi = km * 0.621371;

console.log('From:  San Francisco, CA (37.7749, -122.4194)');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('       (approx. 42.3396, -71.0693)');
console.log();
console.log('Straight-line (great-circle) distance:');
console.log('  ' + km.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('  ' + mi.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
"
